ANNOTATIONS = [
    (1, 'before', '''终端里的 Markdown 表格渲染。核心难题是**没有 CSS**：终端只有等宽网格，列宽必须自己算、折行必须自己切、宽字符必须自己量。整份文件就是一套手写布局算法——三步算列宽、按行折行、垂直居中，最后还有一个「实在放不下就改纵向 key-value」的降级。'''),
    (15, 'before', '''SAFETY_MARGIN 上面那段注释是整份文件里最值得读的一句话：不留够余量，表格会超出父容器，Ink 的裁剪在**相邻两帧可能裁得不一样**，于是滚动区里出现无限闪烁。终端 UI 里「超出一点」不是视觉瑕疵，是致命 bug——所以宁可少用 4 列。'''),
    (25, 'before', '''`MAX_ROW_LINES = 4`：任何一行折行后超过 4 行，就整体改用纵向格式。这是一个**可读性阈值**而不是容量阈值——横向表格里某格占 5 行时，同一行的其他格大部分是空白，扫读反而比 key-value 更累。'''),
    (44, 'before', '''wrapText 是全文件唯一的折行入口，所有单元格都过它。两个参数值得注意：`trim: false` 表示不自动去空格（表格需要保留缩进语义），`hard` 表示允许在词中间断开（列宽比最长单词还窄时只能这么办）。'''),
    (48, 'before', '''长度判断在最前面：`width <= 0` 直接原样返回。这防的是极端情况——终端列数算出负数时（比如 3 列各要 5 字符但终端只有 8 列），若继续交给 wrapAnsi 会得到空数组，后面 `lines[0]` 就是 undefined。'''),
    (52, 'before', '''先 `trimEnd()` 再折行。原因写在注释里：单元格内容来自 `formatToken()`，它会给段落类 token 末尾追加换行符；不先去掉就会在格子里多出一行空行，整个表格的行高被撑坏。'''),
    (59, 'before', '''折完再过滤空行，且**至少返回一个空字符串**。这两条都是为了让「单元格行数」这个值有确定语义：过滤空行保证多行内容里的连续换行不会变成多行空白，兜底返回 `['']` 保证每个格子至少占一行，后面算垂直居中时不会除以零。'''),
    (72, 'before', '''组件本体没有 `_c(N)`——它是手写 memo 化的普通组件（这份文件整体没走 React Compiler）。所以它把辅助函数都定义在组件内部（formatCell / getMinWidth 等），靠闭包拿 theme 与 highlight；代价是每次渲染重建函数，收益是能直接读 props 而不用层层传参。'''),
    (84, 'before', '''`formatCell` 是「单元格 → ANSI 字符串」的唯一入口：把一组 token 逐个交给 `formatToken` 渲染再拼起来。传入的 `0, null, null` 分别是嵌套深度、父 token、列表上下文——表格单元格里不做嵌套缩进，所以深度恒为 0。'''),
    (94, 'before', '''`getMinWidth` 取**最长单词的宽度**，这就是「不硬断词」的下限。注意对空内容返回 `MIN_COLUMN_WIDTH`（3）而不是 0：列宽为 0 会让边框重叠、表格在视觉上「碎掉」。'''),
    (126, 'before', '''边框开销算得很具体：`1 + numCols * 3`。拆开是「最左一条竖线」加上「每列 2 个内边距 + 1 条竖线」。这种把边框当算术题算的写法在终端布局里很常见，因为 Box 的 border 会真实占用列数，算错一列就溢出。'''),
    (137, 'before', '''列宽分配是三档而不是两档，这是本文件的核心算法。①理想宽能放下 → 直接用理想宽，表格不会撑满整行、看起来自然；②最小宽能放下 → 每列先给最小宽，剩余空间按各列「溢出量」的比例分配；③最小宽都放不下 → 等比缩放并允许硬断词。三档的分界条件分别是 totalIdeal、totalMin 与可用宽的比较，所以这两个和必须提前算好。'''),
    (145, 'before', '''比例分配用 `Math.floor(overflows[i] / totalOverflow * extraSpace)`，注意是**向下取整**：这样分配的总和只会少于可用宽，不会超。少掉的那几列变成右侧留白，比溢出安全。当 `totalOverflow === 0`（所有列都已达理想宽）时直接返回最小宽，避免除以零。'''),
    (154, 'before', '''最窄档：等比缩放。`Math.max(..., MIN_COLUMN_WIDTH)` 是硬下限——即使算出来每列该分到 1 列，也保底给 3 列，宁可整表溢出（后面有兜底）也不能让列宽小到边框吞掉内容。同时置 `needsHardWrap = true`，后面所有折行都会允许断词。'''),
    (184, 'before', '''算完列宽才知道要不要转纵向，所以这里必须**真的把所有格子折一遍**并取最大行数——这是一次纯测量、不产生输出。看起来浪费，但它换来的是一个准确的判定：只在「确实会很高」时才换成 key-value，而不是靠列数或字符数猜。'''),
    (204, 'before', '''同一行里各格行数不同时**垂直居中**：偏移量取 `floor((maxLines - lines) / 2)`。向上取整会让内容整体偏下、与边框贴太近；向下取整留出的空隙在上方，视觉上更接近「居中」。'''),
    (217, 'before', '''对齐规则是「表头恒居中、数据看 token 的 align」。这是本文件唯一一处**故意不遵守 Markdown 语义**的地方：Markdown 里表头也受 `:---:` 控制，但终端窄表里表头居中明显更好看，所以覆盖掉。'''),
    (241, 'before', '''纵向格式：每条记录之间用一条横线分隔，字段按「**加粗标签**: 值」排列。这是给极窄终端（或宽表塞不下）准备的降级视图——信息一条不少，只是从二维网格变成一维列表。'''),
    (256, 'before', '''值先 `trimEnd()` 再把所有连续空白（含换行）压成单空格。纵向格式是一维流，原文里的换行若不压平，一条记录会被撑成好几行、与下一条的边界模糊。'''),
    (264, 'before', '''**两遍折行**：第一遍按「首行要扣掉标签宽度」的窄宽折，第二遍把首行之后的剩余文本重新按「整行减缩进」的宽折。这么绕是因为首行左边有 `标签:` 占位、续行只有 2 空格缩进，两者可用宽不同；一次性折会浪费续行的空间或让首行溢出。'''),
    (291, 'before', '''纵向格式有**两个**入口：这里（折行后行数超标）和下面 315 行（拼完之后发现仍超宽）。前者是「预判会太高」，后者是「实测溢出」——后者是终端 resize 竞态的唯一兜底，两者都不能省。'''),
    (308, 'before', '''安全兜底：把所有行拼完，实测最宽的一行是否超过 `terminalWidth - SAFETY_MARGIN`，超了就退回纵向格式。注释点明这是为 resize 竞态准备的——列宽是按某一时刻的终端宽度算的，而真正渲染时宽度可能已经变了。'''),
    (319, 'before', '''最终整表放进**一个** `<Ansi>` 块而不是逐行 `<Text>`。原因是 Ink 会对每个 Text 单独做换行决策，逐行渲染时某一行若比容器宽一列，Ink 会在行中间再折一次、把表格撕开；单块 Ansi 里换行符由我们自己控制，Ink 不再插手。'''),
]
